class AvgPartition:
    def __init__(self, lst, limit):
        self._lst = lst
        self._limit = limit

    @property
    def lst(self):
        return self._lst

    @property
    def limit(self):
        return self._limit

    def _partition_size(self):
        return len(self._lst) // self._limit

    def _partition_remainder(self):
        return len(self._lst) % self._limit

    def _start_index(self, index):
        size = self._partition_size()
        remainder = self._partition_remainder()
        return index * size + min(index, remainder)

    def _end_index(self, index):
        size = self._partition_size()
        start = self._start_index(index)
        remainder = self._partition_remainder()
        extra = 1 if index + 1 <= remainder else 0
        return start + size + extra

    def get(self, index):
        start = self._start_index(index)
        end = self._end_index(index)
        return self.lst[start:end]
